<?php
/**
 * InkThread Decoration Pricing
 */
declare(strict_types=1);

namespace InkThread\DecorationPricing\Model\Artwork;

/**
 * A stored artwork file. The path is relative to var/ and generated by the server; the name is display-only.
 */
class ArtworkFile
{
    /**
     * @param string $path relative to var/, under ArtworkStorage::BASE_PATH
     * @param string $name sanitised original file name, for display
     * @param int $size bytes
     * @param string $mimeType detected MIME type
     */
    public function __construct(
        private readonly string $path,
        private readonly string $name,
        private readonly int $size,
        private readonly string $mimeType
    ) {
    }

    /**
     * Storage path relative to var/.
     *
     * @return string
     */
    public function getPath(): string
    {
        return $this->path;
    }

    /**
     * Display name.
     *
     * @return string
     */
    public function getName(): string
    {
        return $this->name;
    }

    /**
     * Size in bytes.
     *
     * @return int
     */
    public function getSize(): int
    {
        return $this->size;
    }

    /**
     * Detected MIME type.
     *
     * @return string
     */
    public function getMimeType(): string
    {
        return $this->mimeType;
    }

    /**
     * Plain array form, used for storage.
     *
     * @return array{path: string, name: string, size: int, mime_type: string}
     */
    public function toArray(): array
    {
        return ['path' => $this->path, 'name' => $this->name, 'size' => $this->size, 'mime_type' => $this->mimeType];
    }
}
